// Collect the Instagram handles from the References tab into a single
// username array for one Apify run (cheaper + faster than one run each).
const handles = [];
for (const item of $input.all()) {
  const raw = item.json.Handle ?? item.json.handle ?? '';
  const h = String(raw).trim().replace(/^@/, '').replace(/\/$/, '');
  if (h) handles.push(h);
}

const usernames = [...new Set(handles)];
if (usernames.length === 0) {
  throw new Error('No handles found in the References tab. Add at least one handle in the "Handle" column (no @, no URL).');
}

return [{ json: { usernames } }];

