// Apify run-sync-get-dataset-items returns a JSON array of post objects.
// Depending on n8n's HTTP node it can arrive either as one item whose
// json IS the array, or as many items. Handle both.
const input = $input.all();
let posts = [];
if (input.length === 1 && Array.isArray(input[0].json)) {
  posts = input[0].json;
} else {
  posts = input.map((i) => i.json).filter(Boolean);
}

const today = new Date().toISOString().slice(0, 10);
const COMMENT_WEIGHT = 5; // comments are scarcer than likes -> weight them
const TOP_N = 25;

const rows = [];
for (const p of posts) {
  if (!p || typeof p !== 'object') continue;

  // keep only video / reel content (that's what gets reposted)
  const type = p.type || '';
  const productType = p.productType || '';
  const isVideo =
    type === 'Video' ||
    productType === 'clips' ||
    typeof p.videoViewCount === 'number' ||
    typeof p.videoPlayCount === 'number';
  if (!isVideo) continue;

  const likes = Number(p.likesCount) || 0;
  const comments = Number(p.commentsCount) || 0;
  const postedAt = p.timestamp || '';

  let hours = 24;
  if (postedAt) {
    const diffMs = Date.now() - new Date(postedAt).getTime();
    if (!Number.isNaN(diffMs)) hours = Math.max(diffMs / 3600000, 1);
  }

  const velocity = (likes + comments * COMMENT_WEIGHT) / hours;
  const score = Math.round(velocity);

  rows.push({
    Date: today,
    SourceHandle:
      p.ownerUsername || (p.parentData && p.parentData.username) || p.inputUrl || '',
    VideoURL: p.url || '',
    Likes: likes,
    Comments: comments,
    PostedAt: postedAt,
    EngagementScore: score,
  });
}

rows.sort((a, b) => b.EngagementScore - a.EngagementScore);
return rows.slice(0, TOP_N).map((r) => ({ json: r }));

// Build one Telegram digest message from the scored rows.
const rows = $('Score & Format Posts').all().map((i) => i.json);
const today = new Date().toISOString().slice(0, 10);

if (rows.length === 0) {
  return [{ json: { message: `IG Discovery ${today}: no new videos passed the filters today.` } }];
}

const lines = [];
lines.push(`\uD83D\uDCCA IG Discovery \u2014 ${today}`);
lines.push(`${rows.length} trending videos pulled from your reference accounts.`);
lines.push('');

rows.slice(0, 5).forEach((r, idx) => {
  lines.push(`${idx + 1}. @${r.SourceHandle}  \u2022  score ${r.EngagementScore}`);
  lines.push(`   ${r.Likes} likes \u00B7 ${r.Comments} comments`);
  lines.push(`   ${r.VideoURL}`);
});

lines.push('');
lines.push('Full list is in the Daily Pulls tab of your sheet.');

return [{ json: { message: lines.join('\n') } }];
